def check_and_save():
    all_ok = True
    shingles = {}
    for filename, data in chapters_data.items():
        title = data["title"]
        paras = data["paragraphs"]
        errs, total_words = validate_chapter(filename, title, paras)
        print(f"--- {filename} ---")
        print(f"Paras: {len(paras)}, Words: {total_words}")
        if errs:
            all_ok = False
            for e in errs:
                print("  ERROR:", e)
        else:
            print("  VALIDATION OK")
            
        for p_idx, p in enumerate(paras, 1):
            cleaned = re.sub(r"[^a-z0-9' ]", "", p.lower())
            ws = cleaned.split()
            # check shingles
            for k in range(0, len(ws) - 12 + 1, 6):
                sh = " ".join(ws[k:k+12])
                shingles[sh] = shingles.get(sh, 0) + 1

    rep = [k for k, v in shingles.items() if v > 2]
    if len(rep) > 5:
        print(f"ERROR: repeated 12-word phrases across chapters: {len(rep)}")
        all_ok = False
    else:
        print(f"Shingle check passed: {len(rep)} repeated shingles (>2).")

    if all_ok:
        print("Writing files to disk...")
        for filename, data in chapters_data.items():
            filepath = os.path.join(TARGET_DIR, filename)
            content = f"# {data['title']}\n\n" + "\n\n".join(data["paragraphs"]) + "\n"
            with open(filepath, "w", encoding="utf-8") as f:
                f.write(content)
            print(f"Saved {filepath}")
    else:
        print("Fix errors before saving.")

check_and_save()
